INSERT INTO `custom_pages` (`id`, `title`, `slug`, `content`, `showLocation`, `displayOrder`, `metaTitle`, `metaDescription`, `bannerUrl`, `downloadItems`, `isPublished`, `createdAt`, `updatedAt`, `metaKeywords`) VALUES
('page-1786378821838', 'Rapid Revision Materials', 'downloads/rapid-revision', '', 'DOWNLOADS_HUB', 1, 'Rapid Revision Materials', '', '', '[{\"id\":\"item-1786870696422-dqqo\",\"title\":\"Bihar Political Map\",\"description\":\"Bihar District Wise Map\",\"type\":\"BPSC\",\"examCategory\":\"BPSC\",\"language\":\"English\",\"editionYear\":\"2025-26 Edition\",\"size\":\"0.4 MB\",\"url\":\"https://finalattemptias.com/uploads/pdfs/Bihar_District_Map_FINAL_ATTEMPT.pdf\",\"thumbnailUrl\":\"\",\"samplePdfUrl\":\"\",\"buyUrl\":\"\"},{\"id\":\"item-1786869412925-l3ee\",\"title\":\"BPSC PRELIMS REVISION TRACKER SHEET\",\"description\":\"BPSC PRELIMS Revision Tracker\\nFINAL ATTEMPT द्वारा तैयार किया गया BPSC Revision Tracker अभ्यर्थियों को अपनी तैयारी और Revision को व्यवस्थित एवं प्रभावी तरीके से Track करने में मदद करने के लिए बनाया गया है।\\nBPSC जैसी प्रतियोगी परीक्षा में केवल पढ़ना पर्याप्त नहीं है; बार-बार Revision करना और उसे सही तरीके से Track करना भी उतना ही महत्वपूर्ण है। यह Tracker आपको Subject-wise Revision की प्रगति पर नजर रखने और अपनी तैयारी को Systematic बनाने में सहायता करेगा।\\n\\n🎯BPSC Revision Tracker की विशेषताएँ:\\nSubject-wise Revision को Track करने की सुविधा\\n\\nप्रत्येक Revision के लिए अलग-अलग कॉलम (R1, R2, R3......)\\n\\nRevision पूरा होने पर ✔️ Tick करके Progress दर्ज करें\\n\\nयह पहचानने में मदद कि किस विषय का कितना Revision हो चुका है\\n\\nकमजोर या कम Revised Topics पर दोबारा ध्यान देने में सहायता\\n\\nपूरी तैयारी को Organized और Systematic तरीके से Manage करने में उपयोगी\\n\\n🎯कैसे उपयोग करें?\\nइस Tracker का Print Out निकालें और अपने Syllabus के अनुसार प्रत्येक Subject का Revision पूरा होने पर संबंधित Revision Column में ✔️ Tick लगाते जाएँ। इससे आपको अपनी तैयारी की वास्तविक स्थिति स्पष्ट रूप से दिखाई देती रहेगी।\\nनियमित Revision को Track करें, अपनी तैयारी को व्यवस्थित करें और परीक्षा से पहले पूरे Syllabus का Multiple Revision सुनिश्चित करें।\\n\\nLet\'s Make Your Attempt Final with FINAL ATTEMPT !\",\"type\":\"BPSC PRELIMS\",\"examCategory\":\"BPSC\",\"language\":\"English\",\"editionYear\":\"2025-26 Edition\",\"size\":\"0.4 MB\",\"url\":\"https://finalattemptias.com/uploads/pdfs/BPSC_Prelims_Revision_Tracker_FINAL_ATTEMPT.pdf\",\"thumbnailUrl\":\"\",\"samplePdfUrl\":\"\",\"buyUrl\":\"\"},{\"id\":\"item-1786422290715-xz2x\",\"title\":\"Rapid Revision Material For BPSC Prelims Final Attempt\",\"description\":\"\",\"type\":\"BPSC Prelims: Bihar Special\",\"size\":\"49.9 MB\",\"url\":\"https://finalattemptias.com/uploads/pdfs/Final_Attempt_Rapid_Revision_Material_BPSC_Prelims.pdf\",\"language\":\"Hindi\",\"thumbnailUrl\":\"https://finalattemptias.com/uploads/images/Screenshot_2026-08-16_140321.webp\"}]', 1, '2026-08-10T16:20:24.244Z', '2026-08-16T08:58:17.550Z', NULL),
('page-1786461937876', 'Final Attempt Publication', 'downloads/fa-publication', '<h3><br></h3>', 'DOWNLOADS_HUB', 1, 'Final Attempt Publication', '', '', '[{\"id\":\"item-1786627679513-tz84\",\"title\":\"Final Attempt: बिहार तथ्य संग्रह\",\"description\":\"Final Attempt: बिहार तथ्य संग्रह\\n\\nBPSC एवं बिहार से जुड़ी प्रतियोगी परीक्षाओं के लिए एक स्मार्ट और Exam-Oriented पुस्तक।\\n\\n“बिहार तथ्य संग्रह” को Topic-Wise PYQs, Trend Analysis और बदलते Exam Pattern को ध्यान में रखकर तैयार किया गया है, ताकि अभ्यर्थी कम समय में महत्वपूर्ण Bihar Topics की प्रभावी तैयारी और Quick Revision कर सकें।\\n\\nप्रमुख विशेषताएँ:\\n• Topic-Wise PYQs\\n• Topic-Wise Trend Analysis\\n• महत्वपूर्ण एवं परीक्षा-उपयोगी तथ्य\\n• सरल और Quick Revision-Friendly प्रस्तुति\\n• BPSC के बदलते पैटर्न के अनुरूप कंटेंट\\n\\nएक ऐसी पुस्तक, जो आपकी Bihar Special तैयारी को बनाए अधिक व्यवस्थित, स्मार्ट और Exam-Oriented।\\n\\nFINAL ATTEMPT - Let’s Make Your Attempt Final.\\n\",\"type\":\"BPSC\",\"examCategory\":\"BPSC\",\"language\":\"Hindi\",\"editionYear\":\"2026 Edition\",\"price\":220,\"size\":\"2.5 MB\",\"url\":\"https://www.amazon.in/dp/8168524624?ref=cm_sw_r_ffobk_cso_wa_apan_dp_3D908TH13SSSWRC8KCYR&ref_=cm_sw_r_ffobk_cso_wa_apan_dp_3D908TH13SSSWRC8KCYR&social_share=cm_sw_r_ffobk_cso_wa_apan_dp_3D908TH13SSSWRC8KCYR&bestFormat=true\",\"thumbnailUrl\":\"https://finalattemptias.com/uploads/images/71rJ4Gp8UyL._SY385_.webp\",\"samplePdfUrl\":\"https://finalattemptias.com/uploads/pdfs/1784804575413_Sample_PDF________________-_________________________FinalAttempt.pdf\",\"buyUrl\":\"\",\"discountedPrice\":190}]', 1, '2026-08-11T15:25:58.633Z', '2026-08-23T05:49:54.119Z', NULL),
('page-1787661175693', 'Useful Documents', 'downloads/useful-documents', '<h3><br></h3>', 'DOWNLOADS_HUB', 1, 'Useful Documents', '', '', '[{\"id\":\"item-1787896836428-vo3c\",\"title\":\"BPSC PRELIMS REVISION TRACKER\",\"description\":\"\",\"type\":\"BPSC PRELIMS REVISION TRACKER\",\"examCategory\":\"BPSC\",\"language\":\"English\",\"editionYear\":\"\",\"discountedPrice\":2,\"size\":\"0.4 MB\",\"url\":\"https://finalattemptias.com/uploads/pdfs/BPSC_Revision_Tracker_FINAL_ATTEMPT.pdf\",\"thumbnailUrl\":\"\",\"samplePdfUrl\":\"\",\"buyUrl\":\"\"}]', 1, '2026-08-25T12:33:07.294Z', '2026-08-28T06:00:37.839Z', NULL),
('page-seo-bpsc-bhagalpur', 'Best BPSC Institute in Bhagalpur - Foundation & Sprint Batches', 'bpsc-institute-in-bhagalpur', '\n      <h1>Best BPSC Institute in Bhagalpur - Foundation & Sprint Batches</h1>\n      <p class=\"lead\">Final Attempt IAS offers structured BPSC guidance, study materials, and answer evaluation in Bhagalpur.</p>\n    ', 'SLUG_ONLY', 7, 'Best BPSC Institute in Bhagalpur | Final Attempt IAS', 'Premier BPSC Institute in Bhagalpur for 71st and 72nd BPSC preparation with comprehensive study materials.', '', '[]', 1, '2026-09-02T18:59:46.644Z', '2026-09-28T16:18:07.573Z', 'bpsc institute in bhagalpur, bpsc coaching bhagalpur, bpsc test series bhagalpur'),
('page-seo-bpsc-delhi', 'Top BPSC Institute in Delhi - Mukherjee Nagar & Karol Bagh Centre', 'bpsc-institute-in-delhi', '\n      <h1>Top BPSC Institute in Delhi - Mukherjee Nagar & Karol Bagh Guidance</h1>\n      <p class=\"lead\">Final Attempt IAS is the premier BPSC Institute in Delhi, catering specifically to UPSC and State PCS aspirants in Mukherjee Nagar, Karol Bagh, and Jia Sarai who are preparing for BPSC Examinations.</p>\n\n      <h2>Why Choose Final Attempt IAS in Delhi?</h2>\n      <ul>\n        <li><strong>UPSC to BPSC Syllabus Transition Mentorship:</strong> Specialized bridge courses for Delhi UPSC aspirants to cover Bihar-specific micro topics.</li>\n        <li><strong>Delhi Expert Faculty Team:</strong> Experienced educators and former civil servants conducting strategic interactive sessions.</li>\n        <li><strong>Hybrid Learning Flexibility:</strong> Combine Delhi offline classroom sessions with 24/7 digital access.</li>\n      </ul>\n    ', 'SLUG_ONLY', 3, 'Top BPSC Institute in Delhi | Bihar PCS Coaching - Final Attempt IAS', 'Leading BPSC Coaching Institute in Delhi for Bihar Public Service Commission (71st & 72nd BPSC) preparation with dedicated mentorship.', '', '[]', 1, '2026-09-02T18:59:46.495Z', '2026-09-28T16:18:04.033Z', 'bpsc institute in delhi, bpsc coaching mukherjee nagar, bpsc coaching karol bagh, best bpsc mentorship delhi, bpsc mains answer writing delhi'),
('page-seo-bpsc-gaya', 'Leading BPSC Institute in Gaya for 71st & 72nd BPSC', 'bpsc-institute-in-gaya', '\n      <h1>Leading BPSC Institute in Gaya for 71st & 72nd BPSC</h1>\n      <p class=\"lead\">Final Attempt IAS extends high-yield BPSC guidance and test series to students in Gaya and South Bihar region.</p>\n    ', 'SLUG_ONLY', 5, 'Leading BPSC Institute in Gaya | Final Attempt IAS', 'Renowned BPSC Coaching Institute in Gaya offering expert mentorship, classroom batches, and test series.', '', '[]', 1, '2026-09-02T18:59:46.574Z', '2026-09-28T16:18:05.800Z', 'bpsc institute in gaya, bpsc coaching gaya, best bpsc test series gaya'),
('page-seo-bpsc-lucknow', 'Best BPSC Institute in Lucknow for Civil Services Aspirants', 'bpsc-institute-in-lucknow', '\n      <h1>Best BPSC Institute in Lucknow for Civil Services Aspirants</h1>\n      <p class=\"lead\">Final Attempt IAS brings top-tier Bihar Public Service Commission (BPSC) and State PCS mentorship to aspirants in Lucknow (Aliganj & Hazratganj student corridors).</p>\n\n      <h2>Key Advantages for Lucknow Aspirants</h2>\n      <ul>\n        <li><strong>Specialized Bihar Special GS & Economic Survey:</strong> Exclusive modules covering Bihar History, Art & Culture, Geography, and Budget for non-Bihar resident aspirants in Lucknow.</li>\n        <li><strong>UPPSC & BPSC Dual Preparation Guidance:</strong> Strategic syllabus mapping between UPPSC and BPSC to maximize selection chances.</li>\n        <li><strong>Rigorous Mains Test Series:</strong> Timed test series with detailed evaluation and model answers.</li>\n      </ul>\n\n      <h2>Courses Offered in Lucknow</h2>\n      <ul>\n        <li><strong>71st BPSC Mains Answer Writing Series</strong></li>\n        <li><strong>72nd BPSC Foundation & NCERT Integrated Batch</strong></li>\n        <li><strong>Current Affairs & Bihar GK Special Modules</strong></li>\n      </ul>\n    ', 'SLUG_ONLY', 2, 'Best BPSC Institute in Lucknow | State PCS Mentorship - Final Attempt IAS', 'Top BPSC Institute in Lucknow providing structured Prelims, Mains and Essay guidance for UP & Bihar State PCS aspirants.', '', '[]', 1, '2026-09-02T18:59:46.460Z', '2026-09-28T16:18:03.053Z', 'bpsc institute in lucknow, bpsc coaching in lucknow, state pcs institute lucknow, best bpsc prelims mains batch lucknow, Bihar GS coaching lucknow'),
('page-seo-bpsc-muzaffarpur', 'Top BPSC Coaching Institute in Muzaffarpur', 'bpsc-institute-in-muzaffarpur', '\n      <h1>Top BPSC Coaching Institute in Muzaffarpur</h1>\n      <p class=\"lead\">Final Attempt IAS provides comprehensive 71st & 72nd BPSC mentorship and test series for aspirants in Muzaffarpur and North Bihar.</p>\n    ', 'SLUG_ONLY', 6, 'Top BPSC Coaching Institute in Muzaffarpur | Final Attempt IAS', 'Top BPSC Institute in Muzaffarpur with personalized mentorship, Mains evaluation, and interview guidance.', '', '[]', 1, '2026-09-02T18:59:46.607Z', '2026-09-28T16:18:06.655Z', 'bpsc institute in muzaffarpur, bpsc coaching muzaffarpur, bpsc gs batch muzaffarpur'),
('page-seo-bpsc-patna', 'Best BPSC Institute in Patna - Top Coaching for 71st & 72nd BPSC', 'bpsc-institute-in-patna', '\n      <h1>Best BPSC Institute in Patna - Top Coaching for 71st & 72nd BPSC</h1>\n      <p class=\"lead\">Final Attempt IAS is recognized as the premier BPSC Coaching Institute in Patna (Boring Road & Kankarbagh Centres), dedicated to empowering civil service aspirants with personalized 1-on-1 mentorship, state-of-the-art classroom sessions, and high-yield Bihar GS notes.</p>\n      \n      <h2>Why Final Attempt IAS is the Top Choice in Patna?</h2>\n      <ul>\n        <li><strong>Comprehensive 71st & 72nd BPSC Integrated Foundation:</strong> Coverage of GS Paper 1, GS Paper 2, Essay Writing, and Bihar Special static & current affairs.</li>\n        <li><strong>Daily Answer Writing & Mains Evaluation:</strong> Evaluated answer copies returned within 48 hours by top BPSC rankers.</li>\n        <li><strong>Small Batch Sizes for Individual Focus:</strong> Personal attention to every student in Patna with daily doubt clearing.</li>\n        <li><strong>Bilingual Batches (Hindi & English Medium):</strong> Separate batch options tailored for both Hindi and English medium aspirants in Bihar.</li>\n      </ul>\n\n      <h2>Patna Learning Centre Highlights</h2>\n      <table>\n        <thead>\n          <tr>\n            <th>Course Program</th>\n            <th>Target Exam</th>\n            <th>Key Offerings</th>\n            <th>Batch Mode</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>71st BPSC Mains Masterclass</td>\n            <td>71st BPSC Mains</td>\n            <td>GS 1 & 2 + Essay + Evaluated Test Series</td>\n            <td>Offline Patna & Live Online</td>\n          </tr>\n          <tr>\n            <td>72nd BPSC Foundation Batch</td>\n            <td>72nd BPSC Prelims & Mains</td>\n            <td>1 Year Integrated Foundation + Micro Notes</td>\n            <td>Offline Patna & Hybrid</td>\n          </tr>\n          <tr>\n            <td>BPSC Prelims Test Series 2025-26</td>\n            <td>BPSC Prelims Sprint</td>\n            <td>35 High-Yield Tests with Detailed Solutions</td>\n            <td>Online & Offline Patna</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h2>Frequently Asked Questions for BPSC Aspirants in Patna</h2>\n      <h3>Q1. Where is Final Attempt IAS located in Patna?</h3>\n      <p>Our mentorship centre and guidance desk are situated conveniently in Patna with access to Boring Road and Kankarbagh student hubs.</p>\n      <h3>Q2. Are online batches available for Patna students?</h3>\n      <p>Yes, all classroom lectures are recorded in HD and streamed live with interactive doubt clearance on our platform.</p>\n    ', 'SLUG_ONLY', 1, 'Best BPSC Institute in Patna | Top Coaching & Mentorship - Final Attempt IAS', 'Premier BPSC Coaching Institute in Patna offering 71st & 72nd BPSC Foundation, Prelims Sprint, Mains Answer Writing & 1-on-1 Interview Mentorship with top faculties.', '', '[]', 1, '2026-09-02T18:59:46.422Z', '2026-09-28T16:18:02.053Z', 'bpsc institute in patna, best bpsc coaching patna, 71st bpsc batch patna, bpsc offline coaching patna, bpsc mains mentorship patna, top bpsc academy patna'),
('page-seo-bpsc-prayagraj', 'Top BPSC Institute in Prayagraj (Allahabad)', 'bpsc-institute-in-prayagraj', '\n      <h1>Top BPSC Institute in Prayagraj (Allahabad)</h1>\n      <p class=\"lead\">Final Attempt IAS serves aspirants in Prayagraj (Katra & Civil Lines) preparing for BPSC & UPPSC examinations with specialized Bihar GS modules.</p>\n    ', 'SLUG_ONLY', 8, 'Top BPSC Institute in Prayagraj / Allahabad | Final Attempt IAS', 'Top-ranked BPSC Institute in Prayagraj (Allahabad) for Bihar Special GS, Mains answer writing and mentorship.', '', '[]', 1, '2026-09-02T18:59:46.678Z', '2026-09-28T16:18:08.451Z', 'bpsc institute in prayagraj, bpsc coaching allahabad, bpsc state pcs prayagraj'),
('page-seo-bpsc-ranchi', 'Best BPSC Institute in Ranchi - Premier State PCS Mentorship', 'bpsc-institute-in-ranchi', '\n      <h1>Best BPSC Institute in Ranchi - Premier State PCS Mentorship</h1>\n      <p class=\"lead\">Final Attempt IAS provides dedicated coaching and mentorship for BPSC and JPSC aspirants in Ranchi (Lalpur & Circular Road).</p>\n\n      <h2>Program Features in Ranchi</h2>\n      <ul>\n        <li><strong>State Specific Customization:</strong> In-depth coverage of Bihar & Jharkhand regional history, geography, and economy.</li>\n        <li><strong>Personalized Performance Analytics:</strong> Track mock test ranks, speed, accuracy, and section-wise strengths.</li>\n      </ul>\n    ', 'SLUG_ONLY', 4, 'Best BPSC Institute in Ranchi | BPSC & JPSC Guidance - Final Attempt IAS', 'Top-rated BPSC Institute in Ranchi providing comprehensive BPSC GS Paper I, II, Essay evaluation and mock test series.', '', '[]', 1, '2026-09-02T18:59:46.538Z', '2026-09-28T16:18:04.912Z', 'bpsc institute in ranchi, bpsc coaching ranchi, bpsc prelims test series ranchi, best state pcs academy ranchi, bpsc mains coaching ranchi');
